package tn.esprit.partnerintelligence.controller;import org.springframework.web.bind.annotation.*;import tn.esprit.partnerintelligence.dto.PartnerIntelligenceOverviewDto;import tn.esprit.partnerintelligence.entity.*;import tn.esprit.partnerintelligence.repository.*;import tn.esprit.partnerintelligence.service.InferenceOrchestratorService;import java.util.List;@RestController @RequestMapping("/api/partner-intelligence/v1") public class PartnerIntelligenceController{ private final InferenceOrchestratorService o; private final RecommendationItemRepository rr; private final AnomalyAlertRepository ar; private final ForecastSnapshotRepository fr; private final PartnerInsightSummaryRepository sr; public PartnerIntelligenceController(InferenceOrchestratorService o,RecommendationItemRepository rr,AnomalyAlertRepository ar,ForecastSnapshotRepository fr,PartnerInsightSummaryRepository sr){this.o=o;this.rr=rr;this.ar=ar;this.fr=fr;this.sr=sr;} @PostMapping("/partners/{partnerId}/run") public PartnerIntelligenceOverviewDto run(@PathVariable Long partnerId){return o.run(partnerId);} @GetMapping("/partners/{partnerId}/recommendations") public List<RecommendationItem> recommendations(@PathVariable Long partnerId){return rr.findByPartnerId(partnerId);} @GetMapping("/anomalies") public List<AnomalyAlert> anomalies(){return ar.findByStatus("OPEN");} @GetMapping("/forecast") public List<ForecastSnapshot> forecasts(){return fr.findAll();} @GetMapping("/summaries") public List<PartnerInsightSummary> summaries(){return sr.findAll();}}